"""Import four complete named insert sections from the saved official 2023 checklist."""
import ast,hashlib,json,re
from pathlib import Path
root=Path('../outputs/baseball-checklists-2023-up')
tree=ast.parse(Path('scripts/topps/import-2023-baseball.py').read_text(encoding='utf-8'))
teams=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='teams' for t in n.targets))
team_re=re.compile(r'^(.*?)\s+('+'|'.join(re.escape(t) for t in sorted(teams,key=len,reverse=True))+r')[®™]?(?:\s+(.*))?$')
text=(root/'2023-topps-chrome.txt').read_text(encoding='utf-8');sections=[]
for ident,title,end,prefix,count in [('future-stars','FUTURE STARS','ULTRA VIOLET ALL STARS','FS-',20),('topps-chrome-titans','TOPPS CHROME TITANS','TOPPS IN TECHNICOLOR','CT-',10),('topps-in-technicolor','TOPPS IN TECHNICOLOR','TOPPS CHROME EXPOSE','TT-',25),('topps-chrome-expose','TOPPS CHROME EXPOSE','LETS GO','TCE-',30)]:
 block=text.split(title+'\n',1)[1].split(end+'\n',1)[0];cards=[]
 for line in block.strip().splitlines():
  row=re.fullmatch(r'('+re.escape(prefix)+r'\d+)\s+(.+)',line.strip());assert row,line
  number,rest=row.groups();subject=team_re.fullmatch(rest);assert subject,line
  player,team,note=subject.groups();cards.append({'id':'2023-topps-chrome-'+number.lower(),'cardNumber':number,'player':player,'team':team,'section':title.title(),'variant':'Base','subjects':[{'name':player,'team':team,**({'note':note} if note else {})}]})
 assert len(cards)==count and {c['cardNumber'] for c in cards}=={prefix+str(i) for i in range(1,count+1)}
 sections.append({'id':ident,'name':title.title(),'kind':'Inserts','cards':cards})
data={'setId':'2023-topps-chrome','sourceUrl':'https://cdn.shopify.com/s/files/1/0662/9749/5709/files/MLB2326-2023ToppsChromeBaseballChecklist.pdf','sourceSha256':hashlib.sha256((root/'2023-topps-chrome.pdf').read_bytes()).hexdigest(),'sections':sections}
Path('scripts/topps/baseball-chrome-2023-inserts.mjs').write_bytes(('// Complete named insert groups from the official checklist; generated by import-chrome-inserts.py.\nexport const baseballChrome2023Inserts = '+json.dumps([data],ensure_ascii=False,separators=(',',':'))+';\n').encode())
print('Imported',sum(len(x['cards']) for x in sections),'cards in',len(sections),'sections')
